import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, uv, mix, smoothstep, sub, float, mul, add, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = THREE;

  const group = new Group();
  group.name = 'hub-journal-card-2';

  // Atlas region aspect (512 x 320) -> 1.6:1
  const aspect = 512 / 320;
  const w = 2.4;
  const h = w / aspect; // 1.5

  // Spec palette
  const surfCol = new Color('#0b0b10');
  const inkCol = new Color('#16161d');
  const paperCol = new Color('#e8ecf2');
  const accentCol = new Color('#ff2a38');

  // Geometry + node material
  const geo = new PlaneGeometry(w, h);
  const mat = new MeshBasicNodeMaterial();
  mat.side = DoubleSide;
  mat.toneMapped = false;
  mat.transparent = true;
  mat.opacity = 0;

  const uY = uv().y;
  const uX = uv().x;

  // Engineered vertical gradient: surface (bottom) -> ink (top), never flat-black
  let base = mix(vec3(surfCol), vec3(inkCol), smoothstep(float(0.0), float(0.92), uY));

  // Subtle paper highlight band at very top
  const topGloss = smoothstep(float(0.86), float(1.0), uY);
  base = mix(base, vec3(paperCol).mul(float(0.20)), topGloss);

  // Accent rule line near bottom edge (signal red)
  const accentLine = smoothstep(float(0.05), float(0.0), uY);
  base = mix(base, vec3(accentCol).mul(float(0.85)), accentLine);

  // Engineered accent corner notch, top-right
  const corner = smoothstep(float(0.94), float(1.0), uX).mul(
    smoothstep(float(0.94), float(1.0), uY)
  );
  base = mix(base, vec3(accentCol).mul(float(0.7)), corner);

  // Vignette for weight at the edges
  const dx = sub(uX, float(0.5));
  const dy = sub(uY, float(0.5));
  const vig = smoothstep(float(0.95), float(0.35), dx.mul(dx).add(dy.mul(dy)).sqrt());
  base = base.mul(vig.mul(float(0.75)).add(float(0.25)));

  mat.colorNode = base;

  // Grain texture overlay (engineered surface) loaded via ctx loader
  let loadedTex = null;
  let texReady = false;
  if (config.imageUrl) {
    ctx
      .textureLoader
      .loadTexture(config.imageUrl)
      .then((t) => {
        loadedTex = t;
        t.colorSpace = SRGBColorSpace;
        const grain = texture(t);
        // grain as a subtle mid-gray modulation (0.7 .. 1.15)
        const mod = grain.rgb.mul(float(0.45)).add(float(0.7));
        mat.colorNode = base.mul(mod);
        mat.needsUpdate = true;
        texReady = true;
      })
      .catch(() => {});
  }

  const mesh = new Mesh(geo, mat);
  mesh.renderOrder = 1;
  group.add(mesh);

  // Entrance: fade-up + weighted-settle scale (power3.out -> power4.out)
  mesh.scale.set(0.92, 0.92, 1.0);
  mesh.position.set(0, 0.4, 0);

  const tl = gsap.timeline({
    defaults: { ease: 'power3.out' },
  });
  tl.to(mat, { opacity: 1, duration: 0.55, ease: 'power2.out' }, 0)
    .to(mesh.position, { y: 0.0, duration: 0.65, ease: 'power2.out' }, 0)
    .to(mesh.scale, { x: 1.04, y: 1.04, duration: 0.5, ease: 'power3.out' }, 0)
    .to(mesh.scale, { x: 1.0, y: 1.0, duration: 0.4, ease: 'power4.out' }, '>-0.05');

  // No interactivity — handlers empty object for adapter compatibility
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    if (tl) tl.kill();
    geo.dispose();
    mat.dispose();
    // Texture is cached by ctx.textureLoader; do not dispose shared asset.
    loadedTex = null;
  };

  return group;
}
